        (r'\b(crowd|audience)\b', 'CROWDS'),
        (r'\b(talk|chat|hello|greeting|line|lets go|here we go|mamma mia|okey dokey|thank you|lets a go|it s a me|im a tired|so long a|press start to play|all right|c mon|gone baby gone|outta apples|made you look|hey)\b', 'VOICES'),
        (r'\b(airplane|plane)\b', 'AIRCRAFT'),
        (r'\b(boat)\b', 'BOATS'),
        (r'\b(train|subway)\b', 'TRAINS'),
        (r'\b(engine|motor|machine|machinery|machnry|winch)\b', 'MACHINES'),
        (r'\b(bell|bells|gong|horn)\b', 'BELLS'),
        (r'\b(whistle|whistling)\b', 'WHISTLES'),
        (r'\b(clay pot|ceramic)\b', 'CERAMICS'),
        (r'\b(clap|clapping)\b', 'HUMAN'),
