    if any(s == 'emotions' for s in folder_labels):
        return assign('GAMEVideo', confidence='low', reason='Explicit character-emotion cue directory; game reaction cue without assuming a spoken/nonverbal voice.')
    if any(s in {'interface', 'interface sounds'} for s in folder_labels):
        return assign(category='USER INTERFACE', reason='Explicit interface directory; interaction subtype unresolved.')
